package com.quincaisoft.finance.application;import com.quincaisoft.finance.api.PeriodCloseGuard;import jakarta.persistence.EntityManager;import org.springframework.stereotype.Component;import java.time.LocalDate;@Component public class ManualJournalPeriodGuard implements PeriodCloseGuard{private final EntityManager em;public ManualJournalPeriodGuard(EntityManager em){this.em=em;}public String domain(){return "journals";}public void verifyCanClose(LocalDate start,LocalDate end){if(em.createQuery("select count(r) from ManualJournal r where r.status in ('DRAFT','IN_REVIEW') and r.businessDate between :s and :e",Long.class).setParameter("s",start).setParameter("e",end).getSingleResult()>0)throw new IllegalStateException("Pending manual journals prevent close");}}